import React, { useEffect } from 'react'
import * as Yup from "yup";
import { useFormik } from "formik";
import { CustomForm, CustomFormItem, CustomTextArea } from '../../../../components';
import { useStateContext } from '../../../../contexts/ContextProvider';
import useApi from '../../../../hooks/useApi';
import hospitalsApi from '../../../../api/hospitals/hospitalsApi';
import { toast } from 'react-toastify';

export default function NursingCarePlanForm({ selectedAdmission,updated,setupdated }) {
    const { currentColor } = useStateContext()


    const createNursingCarePlanApi=useApi(hospitalsApi.hospitalInpatientAction)
    const createNursingCarePlan=async(data)=>{
        setupdated(false)
        await createNursingCarePlanApi.request(data)
    }


    useEffect(()=>{
        if(createNursingCarePlanApi.data){
            if(createNursingCarePlanApi.data.nursing_care_plan){
                toast.success(createNursingCarePlanApi.data.response_message)
                setupdated(true)
                formik.resetForm()

            }
        }
        console.log("createNursingCarePlanApi.data",createNursingCarePlanApi.data)
    },[createNursingCarePlanApi.data])

    const formik = useFormik({
        initialValues: {
            assessment: "",
            nursing_diagnosis: "",
            goals_and_expected_outcome: "",
            nursing_intervention: "",
            rationale: "",
            evaluation: "",
        },

        validationSchema: Yup.object({
            assessment: Yup.string().required().label("Assessment"),
            nursing_diagnosis: Yup.string().required().label("Nursing diagnosis"),
            goals_and_expected_outcome: Yup.string().required().label("Goals and expected outcome"),
            nursing_intervention: Yup.string().required().label("Nursing intervention"),
            rationale: Yup.string().required().label("Rationale"),
            evaluation: Yup.string().required().label("Evaluation"),

        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log("VALZ", values);
            if (selectedAdmission) {

                const data = {
                    "action":"CreateNursingCarePlan",
                    "admission":selectedAdmission.id,
                    "nursing_diagnosis":values.nursing_diagnosis,
                    "assessment":"My assessment",
                    "goals_and_expected_outcome":"My goals and expected outcome",
                    "nursing_intervention":"My nursing inntervention",
                    "rationale":"My rationale",
                    "evaluation":"My eavaluation"
                }
                createNursingCarePlan(data)
            } else {
                // toast.error("No admission details available")
                console.log("No item")
            }


            
        },
    });
    return (
        <div className='w-full'>
            <CustomForm
                layout="horizontal"
                handleFinish={formik.handleSubmit}
                className=" w-full px-2 "
            >

            <div className='grid md:grid-cols-3 grid-cols-1 gap-4  justify-center items-center'>
                <CustomFormItem
                    touched={formik.touched.assessment}
                    error={formik.errors.assessment}
                >
                    <CustomTextArea
                        className="text-start"
                        id="assessment"
                        name="assessment"
                        onChange={formik.handleChange}
                        placeholder="Enter assessment"
                        label="Enter assessment"
                        size="large"
                        type="text"
                        value={formik.values.assessment}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.nursing_diagnosis}
                    error={formik.errors.nursing_diagnosis}
                >
                    <CustomTextArea
                        className="text-start"
                        id="nursing_diagnosis"
                        name="nursing_diagnosis"
                        onChange={formik.handleChange}
                        placeholder="Enter nursing diagnosis"
                        label="Enter nursing diagnosis"

                        size="large"
                        type="text"
                        value={formik.values.nursing_diagnosis}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.nursing_intervention}
                    error={formik.errors.nursing_intervention}
                >
                    <CustomTextArea
                        className="text-start"
                        id="nursing_intervention"
                        name="nursing_intervention"
                        onChange={formik.handleChange}
                        placeholder="Enter nursing intervention"
                        label="Enter nursing intervention"

                        size="large"
                        type="text"
                        value={formik.values.nursing_intervention}
                    />
                </CustomFormItem>

                <CustomFormItem
                    touched={formik.touched.goals_and_expected_outcome}
                    error={formik.errors.goals_and_expected_outcome}
                >
                    <CustomTextArea
                        className="text-start"
                        id="goals_and_expected_outcome"
                        name="goals_and_expected_outcome"
                        onChange={formik.handleChange}
                        placeholder="Enter goals and expected outcome"
                        label="Enter goals and expected outcome"

                        size="large"
                        type="text"
                        value={formik.values.goals_and_expected_outcome}
                    />
                </CustomFormItem>

                <CustomFormItem
                    touched={formik.touched.rationale}
                    error={formik.errors.rationale}
                >
                    <CustomTextArea
                        className="text-start"
                        id="rationale"
                        name="rationale"
                        onChange={formik.handleChange}
                        placeholder="Enter rationale"
                        label="Enter rationale"
                        size="large"
                        type="text"
                        value={formik.values.rationale}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.evaluation}
                    error={formik.errors.evaluation}
                >
                    <CustomTextArea
                        className="text-start"
                        id="evaluation"
                        name="evaluation"
                        onChange={formik.handleChange}
                        placeholder="Enter your evaluation"
                        label="Enter your evaluation"
                        size="large"
                        type="text"
                        value={formik.values.evaluation}
                    />
                </CustomFormItem>
                </div>

                <button
                    id="formikPrescription"
                    style={{ background: currentColor }}
                    className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
                    color="primary"
                    type="submit"
                >
                    Submit
                </button>
            </CustomForm>

        </div>
    )
}
