import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Collapse } from 'antd'

export default function AdmissionPhysioptherapyOrders({selectedAdmission}) {
         const [admissionPhysiotherapyOrders, setadmissionPhysiotherapyOrders] = useState([])
            
              const [data, setData] = useState([])
            
              const getAdmissionPhysiotherapyOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
              const getAdmissionPhysiotherapyOrders = async (id) => {
                await getAdmissionPhysiotherapyOrdersApi.request({
                  "action": "GetAdmissionPhysiotherapyOrders",
                  "admission": id
                })
              }
              useEffect(() => {
                if (selectedAdmission) {
            
                  getAdmissionPhysiotherapyOrders(selectedAdmission.id)
                }
            
              }, [selectedAdmission])
              useEffect(() => {
                if (getAdmissionPhysiotherapyOrdersApi.data) {
                  if (getAdmissionPhysiotherapyOrdersApi.data.length) {
                    setadmissionPhysiotherapyOrders(getAdmissionPhysiotherapyOrdersApi.data)
                  }
                }
            
                console.log("getAdmissionPhysiotherapyOrdersApi.data", getAdmissionPhysiotherapyOrdersApi.data)
              }, [getAdmissionPhysiotherapyOrdersApi.data])
            
            
              useEffect(() => {
                if (admissionPhysiotherapyOrders) {
                  if (admissionPhysiotherapyOrders.length) {
                    setData(admissionPhysiotherapyOrders.map((i, index) => ({
                      label: `${i.created}  ${i.destination_department_title}`,
                      key: index+1,
                      children: <div>
                        {
                          i.examinations && i.examinations.length ? <div>
            
                            {
                              i.examinations.map((y,yIn) => {
                                return <div>
                                  <p className=''>
                                  <span className='mx-2'>{yIn+1}.</span>
                                  <span className='mx-2'>{y.examination_title}</span>
                                  <span className='mx-2 font-semibold'>KES {parseFloat(y.examination_charge).toFixed(2).toString()}</span>
                                  </p>
            
                                </div>
                              })
                            }
                          </div> : <div></div>
                        }
                      </div>
                    })))
                  }
                }
            
                console.log("getDependantPhysiotherapyOrdersApi.data", getAdmissionPhysiotherapyOrdersApi.data)
              }, [admissionPhysiotherapyOrders])
    return (
        <div>
    <p className='text-2xl font-semibold text-center'>Admission Physiotherapy Orders</p>
    {data && data.length ? <Collapse items={data} defaultActiveKey={['1']} /> : <>
      <p className='text-center'>No items retrieved</p>
      </>}
    </div>
    )
}
