import React, { useEffect, useState } from 'react'
import ComprehensionFirstCadexForm from './ComprehensionFirstCadexForm'
import ComprehensionFirstCadexDetails from './ComprehensionFirstCadexDetails'
import { toast } from 'react-toastify'
import useApi from '../../../../hooks/useApi'
import { useLocation } from 'react-router-dom'
import { useStateContext } from '../../../../contexts/ContextProvider'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'

export default function ComprehensionFirstCadex() {

        const [selectedAdmission, setselectedAdmission] = useState()
        const [comprehensionFirstcadex, setcomprehensionFirstcadex] = useState()
        const [errors, setErrors] = useState([])
          const [showForm, setshowForm] = useState(comprehensionFirstcadex?true:false)
    
        const location = useLocation()
        const [selectedDependantId, setselectedDependantId] = useState()
        useEffect(() => {
            setselectedDependantId(location.state.dependant)
        }, [location])
    
    
        //Get admission
    
        const getAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
        const getDependantAdmission = async (id) => {
            await getAdmissionApi.request({
                "action": "GetDependantAdmission",
                "dependant": id
            })
        }
    
        useEffect(() => {
            if (errors && errors.length) {
                errors.map((x) => {
                    toast.error(x);
                });
            }
        }, [errors]);
        useEffect(() => {
            if (getAdmissionApi.data) {
    
                if (getAdmissionApi.data.admission) {
                    setselectedAdmission(getAdmissionApi.data.admission)
                }
            }
    
            console.log("getAdmissionApi.data", getAdmissionApi.data)
        }, [getAdmissionApi.data])
    
        useEffect(() => {
            if (selectedDependantId) {
                getDependantAdmission(selectedDependantId)
            }
    
        }, [selectedDependantId])


        const getComprehensionFirstCadexEntryApi = useApi(hospitalsApi.hospitalInpatientAction)
        const getComprehensionFirstCadexEntry=async()=>{
            await getComprehensionFirstCadexEntryApi.request({
                "action":"GetComprehensionFirstCadexEntry",
                "admission":selectedAdmission.id
            
            })
        }

        useEffect(()=>{
            if(getComprehensionFirstCadexEntryApi.data){
                if(getComprehensionFirstCadexEntryApi.data.comprehension_first_cadex){
                    setcomprehensionFirstcadex(getComprehensionFirstCadexEntryApi.data.comprehension_first_cadex)
                }
            }
            console.log("getComprehensionFirstCadexEntryApi.data",getComprehensionFirstCadexEntryApi.data)
        },[getComprehensionFirstCadexEntryApi.data])

       useEffect(()=>{

        if(selectedAdmission){
            getComprehensionFirstCadexEntry();
        }

       },[selectedAdmission]) 

    return (
        <div>
            <p className='text-xl font-semibold text-center'>Comprehension First Cadex</p>
            {showForm?<ComprehensionFirstCadexForm selectedAdmission={selectedAdmission} comprehensionFirstcadex={comprehensionFirstcadex} setcomprehensionFirstcadex={setcomprehensionFirstcadex} />:<div></div>}
            {comprehensionFirstcadex?<ComprehensionFirstCadexDetails comprehensionFirstcadex={comprehensionFirstcadex}/>:<div></div>}

        </div>
    )
}
