import React, { useEffect, useState } from "react";
import {
  CustomForm,
  CustomInput,
  DeleteIcon,
  YesNoModal,
} from "../../../components";
import { useFormik } from "formik";
import * as Yup from "yup";
import { toast, ToastContainer } from "react-toastify";
import { Button, Card, Flex, Table } from "antd";
import useApi from "../../../hooks/useApi";
import productsApi from "../../../api/productsApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";

export default function LaboratoryOrdersForm({
  openLaboratoryOrder,
  setopenLaboratoryOrder,
  selectedDependant,
}) {
  const columns = [
    {
      title: "Service Title",
      dataIndex: "laboratory_service_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Charges",
      dataIndex: "charge",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Time To Result UNit",
      dataIndex: "time_to_result_unit",
    },
    {
      title: "Time To Result",
      dataIndex: "time_to_result",
    },
  ];
  const [user, setuser] = useState();
  const [searchText, setsearchText] = useState("");
  const [yesNoModal, setyesNoModal] = useState(false);
  const [mylocalOrder, setmylocalOrder] = useState(openLaboratoryOrder)
const [errors, setErrors] = useState([])
  const [preparations, setPreparations] = useState();
  const [preparationsData, setpreparationsData] = useState([]);
  const [selectedExamination, setselectedExamination] = useState();
  const { currentColor } = useStateContext();


    useEffect(() => {
      if (errors && errors.length) {
        errors.map((x) => {
          toast.error(x);
        });
      }
    }, [errors]);

  //Delete laboratory examination froim laboratory order
  const deleteLaboratoryExaminationApi=useApi(hospitalsApi.hospitalStaffAction)
  const handleDeleteLaboratoryExaminationAction = (item) => {
    console.log("item to delete",item)
    deleteLaboratoryExaminationApi.request({
        "action":"DeleteLaboratoryExamination",
        "laboratory_examination":item.id
    })
  };


  useEffect(() => { console.log("openLaboratoryOrder", openLaboratoryOrder) }, [openLaboratoryOrder])

  useEffect(() => {
    if (deleteLaboratoryExaminationApi.data) {
      if (
        deleteLaboratoryExaminationApi.data.laboratory_order
       
      ) {
        toast.success(deleteLaboratoryExaminationApi.data.response_message);
        setselectedExamination(null);
        setmylocalOrder(deleteLaboratoryExaminationApi.data.laboratory_order)
      } else {
        toast.error(deleteLaboratoryExaminationApi.data.response_message);
        setselectedExamination(null);
      }
    }
    console.log("deleteLaboratoryExaminationApi.data",deleteLaboratoryExaminationApi.data)
  }, [deleteLaboratoryExaminationApi.data]);




  const prescriptionFormik = useFormik({
    initialValues: {
      facility_sub_store: "",
    },

    validationSchema: Yup.object({
      facility_sub_store: Yup.object().required("Select destination pharmacy"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      const data = {
        action: "CreateHospitalPrescription",
        department: user.employment_department,
        dependant: selectedDependant.id,
        facility_sub_store: values.facility_sub_store.value,
      };

      console.log("datume", data);

      resetForm();
    },
  });

  //Search generics
  const handleChange = (e) => {
    console.log("change", e.target.value);
    setsearchText(e.target.value);
  };

  //Search Laboratory Tests

  const entityLaboratoryServicesApi = useApi(hospitalsApi.hospitalStaffAction);

  const retrieveEntityLaboratoryServices = async (data) => {
    // setPreparations([]);
    // setselectedPreparation(null);
    // console.log("deeppp",mylocalOrder.department)

    await entityLaboratoryServicesApi.request({
      action: "GetEntityLaboratoryServices",
      department: mylocalOrder.destination_department,
    });
  };

  useEffect(() => {
    if (entityLaboratoryServicesApi.data && entityLaboratoryServicesApi.data.length) {
      setPreparations(entityLaboratoryServicesApi.data);
    }
    console.log("entityLaboratoryServicesApi.data",entityLaboratoryServicesApi.data)
  }, [entityLaboratoryServicesApi.data]);

  useEffect(() => {
    if (searchText !== "") {
      handleFilter(searchText);
    }
  }, [searchText]);




  useEffect(() => {
    retrieveEntityLaboratoryServices();
  }, []);

  //Handle selection
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);

  const onSelectChange = (newSelectedRowKeys, selectedRow) => {
    setselectedExamination(selectedRow[0]);
    setSelectedRowKeys(newSelectedRowKeys);
  };

  useEffect(() => {
    if (selectedExamination) {
      setyesNoModal(true);
    }
  }, [selectedExamination]);
  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  useEffect(() => {
    setpreparationsData(preparations);
  }, [preparations]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      preparations &&
      preparations.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setpreparationsData(
        preparations.filter((x) =>
          x.laboratory_service_title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setpreparationsData(preparations);
    }
  };

  useEffect(() => {
    if (selectedExamination) {
      toast.success(selectedExamination.laboratory_service_title);
      setyesNoModal(true);
    }
  }, [selectedExamination]);

  const createLaboratoryExaminationApi = useApi(
    hospitalsApi.hospitalStaffAction
  );

  const addItemToOrder = async () => {
    toast.warn("Add item to order");
    setyesNoModal(false);

    const data = {
        action: "CreateLaboratoryExamination",
        laboratory_order: openLaboratoryOrder.id,
        examination: selectedExamination.id,
      }
    console.log("datass", data)
    await createLaboratoryExaminationApi.request(data);

  };

  useEffect(() => {
    if (createLaboratoryExaminationApi.data) {
      if (
        createLaboratoryExaminationApi.data.laboratory_order
       
      ) {
        toast.success(createLaboratoryExaminationApi.data.response_message);
        setselectedExamination(null);
        setmylocalOrder(createLaboratoryExaminationApi.data.laboratory_order)
      } else {
        toast.error(createLaboratoryExaminationApi.data.response_message);
        setselectedExamination(null);
      }
    }
    console.log("createLaboratoryExaminationApi.data",createLaboratoryExaminationApi.data)
  }, [createLaboratoryExaminationApi.data]);

  const updatelaboratoryOrderApi=useApi(hospitalsApi.hospitalStaffAction)

  const handleCloseLaboratoryOrder=async()=>{
    await updatelaboratoryOrderApi.request({
        "action":"UpdateLaboratoryOrder",
        "laboratory_order":openLaboratoryOrder.id,
        "is_closed":"true"
     
    })
  }

  useEffect(()=>{

    if(updatelaboratoryOrderApi.data ){
        if(updatelaboratoryOrderApi.data.laboratory_order){
            toast.success(updatelaboratoryOrderApi.data.response_message)
            setopenLaboratoryOrder(null)
        }

        if(updatelaboratoryOrderApi.data.errors){
          
            setErrors(updatelaboratoryOrderApi.data.errors)
        }
    }

    console.log("updatelaboratoryOrderApi.data",updatelaboratoryOrderApi.data)
  },[updatelaboratoryOrderApi.data])

  return (
    <div className="w-full  border-1 border-gray-200 shadow-sm rounded-sm px-2 my-5 bg-white">
      <p className="text-2xl font-semibold text-center my-2">
        Pathology Requisitions
      </p>
      <CustomForm
        className=" my-5 md:w-full"
        layout="vertical"
        handleFinish={prescriptionFormik.handleSubmit}
      >
        <div className="border-2 border-gray-400 rounded-md my-5 p-5">
          <p className="text-1xl font-semibold text-center my-2">
            Add Pathology Examination
          </p>
          <div className="grid grid-cols-1  gap-2">
            <div className="col-span-8 bg-gray-50 p-5">
              <ToastContainer theme="colored" position="bottom-center" />
              <CustomInput
                className="w-full h-14 mt-5"
                size="large"
                id="search"
                name="search"
                label="Search pathology examination by name"
                placeholder="Search pathology examination by name"
                onChange={handleChange}
                value={searchText}
              />
              <div>
                <Flex className="mt-5" gap="middle" vertical>
                  <Table
                    rowSelection={{
                      type: "radio",
                      ...rowSelection,
                    }}
                    columns={columns}
                    dataSource={preparationsData}
                  />

                  {yesNoModal && selectedExamination && (
                    <YesNoModal
                      showModal={yesNoModal}
                      setyesNoModal={setyesNoModal}
                      title={selectedExamination.laboratory_service_title}
                      content={"Add this item to order"}
                      yesAction={addItemToOrder}
                    />
                  )}
                  {mylocalOrder && mylocalOrder.is_closed==="false" ? (
                    <div className="w-full">
                      <p className="text-1xl font-semibold text-center my-2">Ordered Pathology Examinations</p>
                      <div>
                        {mylocalOrder &&
                          mylocalOrder.examinations &&
                          mylocalOrder.examinations.length &&
                          mylocalOrder.examinations.map((x, index) => {
                            return (
                              <Card>
                                <div className="grid md:grid-cols-3 grid-cols-2">
                                  <div className="flex flex-col border-1 border-gray-200 p-2">
                                    <p>ITEM</p>
                                    <p className="font-bold">{x.examination_name}</p>
                                  </div>
                                  <div className="flex flex-col border-1 border-gray-200 p-2">
                                    <p>CHARGE</p>
                                    <p className="font-bold">{x.examination_charge}</p>
                                  </div>
                      

                                  <div className="flex flex-col border-1 border-gray-200 p-2 items-center justify-center">
                                    <p>REMOVE</p>
                                    <span className="text-lg text-default-400 cursor-pointer active:opacity-50  justify-center">
                                      <DeleteIcon
                                        onClick={() => handleDeleteLaboratoryExaminationAction(x)}
                                      />
                                    </span>
                                  </div>
                                </div>
                              </Card>
                            );
                          })}
                      </div>
                    </div>
                  ) : (
                    <div></div>
                  )}
                </Flex>
              </div>
            </div>
          </div>
        </div>

        <div className="flex w-full items-center mt-2 justify-center col-span-1 md:col-span-2">
          <Button
            style={{
              background: currentColor,
              color: "white",
              width: 123,
              height: 50,
            }}
            onClick={()=>handleCloseLaboratoryOrder()}
            className="w-36 rounded-md"
            color="primary"
            type="default"
          >
            Confirm and Close
          </Button>
        </div>
      </CustomForm>
    </div>
  );
}
