import React, { useEffect } from 'react'
import * as Yup from "yup";
import { useStateContext } from '../../../../contexts/ContextProvider'
import { useFormik } from "formik";
import { CustomForm, CustomFormItem, CustomInput, CustomTextArea } from '../../../../components'
import useApi from '../../../../hooks/useApi';
import hospitalsApi from '../../../../api/hospitals/hospitalsApi';
import { toast, ToastContainer } from 'react-toastify';

export default function ComprehensionFirstCadexForm({ selectedAdmission,comprehensionFirstcadex, setcomprehensionFirstcadex }) {

  const { currentColor } = useStateContext()



const createComprehensionFirstcadexApi = useApi(hospitalsApi.hospitalInpatientAction)
  const createComprehensionFirstcadex=async(data)=>{
    await createComprehensionFirstcadexApi.request(data)
  }


  useEffect(()=>{

    if(createComprehensionFirstcadexApi.data){

      if(createComprehensionFirstcadexApi.data.comprehension_first_cadex){
        toast.success(createComprehensionFirstcadexApi.data.response_message)
        setcomprehensionFirstcadex(createComprehensionFirstcadexApi.data.comprehension_first_cadex)
      }
    }
    console.log("createComprehensionFirstcadexApi.data",createComprehensionFirstcadexApi.data)
  },[createComprehensionFirstcadexApi.data])
  const formik = useFormik({
    initialValues: {
      head: "",
      neck: "",
      chest: "",
      upper_extremeties: "",
      abdomen: "",
      palpation: "",
      ausculation: "",
      inspection: "",
      respiration: "",
      temparature: "",
      pulse: "",
      diastolic_pressure: "",
      systolic_pressure: "",
      lower_extremeties: "",
    },

    validationSchema: Yup.object({
      head: Yup.string().required().label("Head observation"),
      neck: Yup.string().required().label("Neck observation"),
      chest: Yup.string().required().label("Chest observation"),
      upper_extremeties: Yup.string().required().label("Upper extremeties observation"),
      abdomen: Yup.string().required().label("Abdomen observation"),
      palpation: Yup.string().required().label("Palpation entry"),
      inspection: Yup.string().required().label("Inspection entry"),
      respiration: Yup.string().required().label("Respiration entry"),
      temparature: Yup.string().required().label("Body temparature entry"),
      pulse: Yup.string().required().label("Pulse entry"),
      diastolic_pressure: Yup.string().required().label("Diastolic pressure entry"),
      systolic_pressure: Yup.string().required().label("Systolic pressure entry"),
      ausculation: Yup.string().required().label("Ausculation entry"),
      lower_extremeties: Yup.string().required().label("Lower extremeties observation"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      const data = {
        "action": "CreateComprehensionFirstCadex",
        "admission": selectedAdmission.id,
        "neck": formik.values.neck,
        "chest": formik.values.chest,
        "upper_extremities": formik.values.upper_extremeties,
        "abdomen": formik.values.abdomen,
        "head": formik.values.head,
        "lower_extremities": formik.values.lower_extremeties,
        "ausculation": formik.values.ausculation,
        "inspection": formik.values.inspection,
        "palpation": formik.values.palpation,
        "temparature": formik.values.temparature,
        "respiration": formik.values.respiration,
        "pulse": formik.values.pulse,
        "diastolic_pressure": formik.values.diastolic_pressure,
        "systolic_pressure": formik.values.systolic_pressure,
      }

      createComprehensionFirstcadex(data)

    },
  });


  return (
    <div className='w-full'><CustomForm
      layout="horizontal"
      handleFinish={formik.handleSubmit}
      className=" justify-center items-center w-full px-2 "
    >
    <ToastContainer theme='colored' position='bottom-center'/>
      <div className='grid grid-cols-1 md:grid-cols-3 gap-1'>
        <CustomFormItem
          touched={formik.touched.head}
          error={formik.errors.head}
        >

          <CustomTextArea
            className="text-start"
            id="head"
            name="head"
            onChange={formik.handleChange}
            placeholder="Head"
            label="Head"
            size="large"
            type="text"
            value={formik.values.head}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.neck}
          error={formik.errors.neck}
        >

          <CustomTextArea
            className="text-start"
            id="neck"
            name="neck"
            onChange={formik.handleChange}
            placeholder="Neck"
            label="Neck"
            size="large"
            type="text"
            value={formik.values.neck}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.chest}
          error={formik.errors.chest}
        >
          <CustomTextArea
            className="text-start"
            id="chest"
            name="chest"
            onChange={formik.handleChange}
            placeholder="Chest"
            label="Chest"
            size="large"
            type="text"
            value={formik.values.chest}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.upper_extremeties}
          error={formik.errors.upper_extremeties}
        >
          <CustomTextArea
            className="text-start"
            id="upper_extremeties"
            name="upper_extremeties"
            onChange={formik.handleChange}
            placeholder="Upper extremeties"
            label="Upper extremeties"
            size="large"
            type="text"
            value={formik.values.upper_extremeties}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.abdomen}
          error={formik.errors.abdomen}
        >
          <CustomTextArea
            className="text-start"
            id="abdomen"
            name="abdomen"
            onChange={formik.handleChange}
            placeholder="Abdomen"
            label="Abdomen"
            size="large"
            type="text"
            value={formik.values.abdomen}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.inspection}
          error={formik.errors.inspection}
        >
          <CustomTextArea
            className="text-start"
            id="inspection"
            name="inspection"
            onChange={formik.handleChange}
            placeholder="Inspection"
            label="Inspection"
            size="large"
            type="text"
            value={formik.values.inspection}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.palpation}
          error={formik.errors.palpation}
        >
          <CustomTextArea
            className="text-start"
            id="palpation"
            name="palpation"
            onChange={formik.handleChange}
            placeholder="Palpation"
            label="Palpation"
            size="large"
            type="text"
            value={formik.values.palpation}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.ausculation}
          error={formik.errors.ausculation}
        >
          <CustomTextArea
            className="text-start"
            id="ausculation"
            name="ausculation"
            onChange={formik.handleChange}
            placeholder="Ausculation"
            label="Ausculation"
            size="large"
            type="text"
            value={formik.values.ausculation}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.lower_extremeties}
          error={formik.errors.lower_extremeties}
        >
          <CustomTextArea
            className="text-start"
            id="lower_extremeties"
            name="lower_extremeties"
            onChange={formik.handleChange}
            placeholder="Lower extremeties"
            label="Lower extremeties"
            size="large"
            type="text"
            value={formik.values.lower_extremeties}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.vaginal_examination}
          error={formik.errors.vaginal_examination}
        >
          <CustomTextArea
            className="text-start"
            id="vaginal_examination"
            name="vaginal_examination"
            onChange={formik.handleChange}
            placeholder="Vaginal examinations"
            label="Vaginal examinations"
            size="large"
            type="text"
            value={formik.values.vaginal_examination}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.temparature}
          error={formik.errors.temparature}
        >
          <CustomInput
            className="text-start"
            id="temparature"
            name="temparature"
            onChange={formik.handleChange}
            placeholder="Body temparature"
            label="Body temparature"
            size="large"
            type="number"
            value={formik.values.temparature}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.pulse}
          error={formik.errors.pulse}
        >
          <CustomInput
            className="text-start"
            id="pulse"
            name="pulse"
            onChange={formik.handleChange}
            placeholder="Pulse"
            label="Pulse"
            size="large"
            type="number"
            value={formik.values.pulse}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.respiration}
          error={formik.errors.respiration}
        >
          <CustomInput
            className="text-start"
            id="respiration"
            name="respiration"
            onChange={formik.handleChange}
            placeholder="Respiration"
            label="Respiration"
            size="large"
            type="number"
            value={formik.values.respiration}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.diastolic_pressure}
          error={formik.errors.diastolic_pressure}
        >
          <CustomInput
            className="text-start"
            id="diastolic_pressure"
            name="diastolic_pressure"
            onChange={formik.handleChange}
            placeholder="Diastolic Pressure"
            label="Diastolic Pressure"
            size="large"
            type="number"
            value={formik.values.diastolic_pressure}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.systolic_pressure}
          error={formik.errors.systolic_pressure}
        >
          <CustomInput
            className="text-start"
            id="systolic_pressure"
            name="systolic_pressure"
            onChange={formik.handleChange}
            placeholder="Systolic Pressure"
            label="Systolic Pressure"
            size="large"
            type="number"
            value={formik.values.systolic_pressure}
          />
        </CustomFormItem>

      </div>
      <button
        id="formikPrescription"
        style={{ background: currentColor }}
        className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
        color="primary"
        type="submit"
      >
        Submit
      </button>
    </CustomForm></div>
  )
}
