import React, { useEffect } from 'react'
import { CustomForm, CustomFormItem, CustomInput, CustomTextArea } from '../../../../components'
import * as Yup from "yup";
import { useFormik } from "formik";
import { useStateContext } from '../../../../contexts/ContextProvider';
import useApi from '../../../../hooks/useApi';
import hospitalsApi from '../../../../api/hospitals/hospitalsApi';

export default function PatientNursingCadexForm({ selectedAdmission,updated,setupdated }) {
    const { currentColor } = useStateContext()


    const createPatientNursingCadexEntryApi=useApi(hospitalsApi.hospitalInpatientAction)
    const createPatientNursingCadexEntry =async(data)=>{
        setupdated(false)
        await createPatientNursingCadexEntryApi.request(data)
    }


    useEffect(()=>{
        if(createPatientNursingCadexEntryApi.data){
            if(createPatientNursingCadexEntryApi.data.patient_nursing_cadex_entry){

                setupdated(true)
            }
        }
        console.log("createPatientNursingCadexEntryApi.data",createPatientNursingCadexEntryApi.data)

    },[createPatientNursingCadexEntryApi.data])

    const formik = useFormik({
        initialValues: {
           
            entry: "",
        },

        validationSchema: Yup.object({
            entry: Yup.string().required().label("Comments"),
           
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log("VALZ", values);
            if (selectedAdmission) {

                const data = {
                    "action":"CreatePatientNursingCadexEntry",
                    "admission":selectedAdmission.id,
                    "entry":values.entry
                }
                createPatientNursingCadexEntry(data)
            } else {
                // toast.error("No admission details available")
                console.log("No item")
            }


        },
    });
    return (
        <div className='w-full'>

            <CustomForm
                layout="horizontal"
                handleFinish={formik.handleSubmit}
                className="grid grid-cols-1  gap-4  justify-center items-center w-full px-2 "
            >
                <CustomFormItem
                    touched={formik.touched.entry}
                    error={formik.errors.entry}
                >
                    <CustomTextArea
                        className="text-start"
                        id="entry"
                        name="entry"
                        onChange={formik.handleChange}
                        placeholder="Enter entry"
                        label="Enter entry"
                        rows={4}
                        size="large"
                        type="text"
                        value={formik.values.entry}
                    />
                </CustomFormItem>

                <button
                    id="formikPrescription"
                    style={{ background: currentColor }}
                    className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
                    color="primary"
                    type="submit"
                >
                    Submit
                </button>
            </CustomForm>
        </div>
    )
}
