import React, { useEffect, useState } from "react";
import {
  CustomForm,
  CustomInput,
  DeleteIcon,
  YesNoModal,
} from "../../../components";
import { useFormik } from "formik";
import * as Yup from "yup";
import { toast, ToastContainer } from "react-toastify";
import { Button, Card, Flex, Table } from "antd";
import useApi from "../../../hooks/useApi";
import productsApi from "../../../api/productsApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";

export default function PhysiotherapyOrdersForm({
   openPhysiotherapyOrder,
   setopenPhysiotherapyOrder,
  selectedDependant,
}) {
  const columns = [
    {
      title: "Service Title",
      dataIndex: "physiotherapy_service_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Charges",
      dataIndex: "charge",
      render: (text) => <a>{text}</a>,
    },

  ];
  const [user, setuser] = useState();
  const [searchText, setsearchText] = useState("");
  const [yesNoModal, setyesNoModal] = useState(false);
  const [mylocalOrder, setmylocalOrder] = useState(openPhysiotherapyOrder)

  const [radiologyServices, setradiologyServices] = useState();
  const [preparationsData, setpreparationsData] = useState([]);
  const [selectedProcedure, setselectedProcedure] = useState();
  const { currentColor } = useStateContext();


  //Delete radiology examination froim radiology order
  const deletePhysiotherapyProcedureApi=useApi(hospitalsApi.hospitalStaffAction)
  const handleDeletePhysiotherapyProcedureAction = (item) => {
  
    deletePhysiotherapyProcedureApi.request({
        "action":"DeletePhysiotherapyProcedure",
        "physiotherapy_procedure":item.id
    })
  };

  useEffect(() => {
    if (deletePhysiotherapyProcedureApi.data) {
      if (
        deletePhysiotherapyProcedureApi.data.physiotherapy_order
       
      ) {
        toast.success(deletePhysiotherapyProcedureApi.data.response_message);
        setselectedProcedure(null);
        setmylocalOrder(deletePhysiotherapyProcedureApi.data.physiotherapy_order)
        setSelectedRowKeys([])
      } else {
        toast.error(deletePhysiotherapyProcedureApi.data.response_message);
        setselectedProcedure(null);
      }
    }
    console.log("deletePhysiotherapyProcedureApi.data",deletePhysiotherapyProcedureApi.data)
  }, [deletePhysiotherapyProcedureApi.data]);




  const prescriptionFormik = useFormik({
    initialValues: {
      facility_sub_store: "",
    },

    validationSchema: Yup.object({
      facility_sub_store: Yup.object().required("Select destination pharmacy"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      const data = {
        action: "CreateHospitalPrescription",
        department: user.employment_department,
        dependant: selectedDependant.id,
        facility_sub_store: values.facility_sub_store.value,
      };

      console.log("datume", data);

      resetForm();
    },
  });

  //Search generics
  const handleChange = (e) => {
    console.log("change", e.target.value);
    setsearchText(e.target.value);
  };

  //Search Physiotherapy Examinations

  const getEntityPhysiotherapyServicesApi = useApi(hospitalsApi.hospitalStaffAction);

  const retrieveDepartmentServices = async (data) => {
    setradiologyServices([]);
    // setselectedPreparation(null);

    await getEntityPhysiotherapyServicesApi.request({
      action: "GetEntityPhysiotherapyServices",
      department: mylocalOrder.department,
    });
  };

  useEffect(() => {
    if (getEntityPhysiotherapyServicesApi.data && getEntityPhysiotherapyServicesApi.data.length) {
      setradiologyServices(getEntityPhysiotherapyServicesApi.data);
    }
    console.log("getEntityPhysiotherapyServicesApi.data",getEntityPhysiotherapyServicesApi.data)
  }, [getEntityPhysiotherapyServicesApi.data]);

  useEffect(() => {
    if (searchText !== "") {
      handleFilter(searchText);
    }
  }, [searchText]);




  useEffect(() => {
    if(mylocalOrder){
       retrieveDepartmentServices(searchText);
    }
   
  }, [mylocalOrder]);

  useEffect(() => {
    console.log("openPhysiotherapyOrder",openPhysiotherapyOrder)
  }, [openPhysiotherapyOrder]);

  //Handle selection
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [errors, setErrors] = useState([])

  const onSelectChange = (newSelectedRowKeys, selectedRow) => {
    setselectedProcedure(selectedRow[0]);
    setSelectedRowKeys(newSelectedRowKeys);
  };

  useEffect(() => {
    if (selectedProcedure) {
      setyesNoModal(true);
    }
  }, [selectedProcedure]);
  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  useEffect(() => {
    setpreparationsData(radiologyServices);
  }, [radiologyServices]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      radiologyServices &&
      radiologyServices.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setpreparationsData(
        radiologyServices.filter((x) =>
          x.radiology_service_title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setpreparationsData(radiologyServices);
    }
  };

  useEffect(() => {
    if (selectedProcedure) {
      toast.success(selectedProcedure.radiology_service_title);
      setyesNoModal(true);
    }
  }, [selectedProcedure]);

  const createPhysiotherapyProcedureApi = useApi(
    hospitalsApi.hospitalStaffAction
  );

  const addItemToOrder = async () => {
  
    setyesNoModal(false);

      await createPhysiotherapyProcedureApi.request({
        action: "CreatePhysiotherapyProcedure",
        physiotherapy_order: mylocalOrder.id,
        procedure: selectedProcedure.id,
      });
    
  };

  useEffect(() => {
    if (createPhysiotherapyProcedureApi.data) {
      if (
        createPhysiotherapyProcedureApi.data.physiotherapy_order
       
      ) {
        toast.success(createPhysiotherapyProcedureApi.data.response_message);
        setselectedProcedure(null);
        setmylocalOrder(createPhysiotherapyProcedureApi.data.physiotherapy_order)
      } else {
        toast.error(createPhysiotherapyProcedureApi.data.response_message);
        setselectedProcedure(null);
        
      }
    }
    console.log("createPhysiotherapyProcedureApi.data",createPhysiotherapyProcedureApi.data)
  }, [createPhysiotherapyProcedureApi.data]);




  //Update radiology order
  
  const updateRadiologyOrderApi=useApi(hospitalsApi.hospitalStaffAction)

  const handleCloseRadiologyOrder=async()=>{
    await updateRadiologyOrderApi.request({
        "action":"UpdatePhysiotherapyOrder",
        "physiotherapy_order":mylocalOrder.id,
        "is_closed":"true"
     
    })
  }


      useEffect(() => {
        if (errors && errors.length) {
          errors.map((x) => {
            toast.error(x);
          });
        }
      }, [errors]);

  useEffect(()=>{

    if(updateRadiologyOrderApi.data ){
        if(updateRadiologyOrderApi.data.physiotherapy_order){
            toast.success(updateRadiologyOrderApi.data.response_message)
            setmylocalOrder(null)
            setopenPhysiotherapyOrder(null)
        }

        if(updateRadiologyOrderApi.data.errors){
          
            setErrors(updateRadiologyOrderApi.data.errors)
        }
    }

    console.log("updateRadiologyOrderApi.data",updateRadiologyOrderApi.data)
  },[updateRadiologyOrderApi.data])



  return (
    <div className="w-full  border-1 border-gray-200 shadow-sm rounded-sm px-2 my-2">
    <ToastContainer theme="colored" position="bottom-center"/>
      <p className="text-xl font-semibold text-center my-2">
        Physiotherapy Requisitions
      </p>

      
      <CustomForm
        className=" my-5 md:w-full"
        layout="vertical"
        handleFinish={prescriptionFormik.handleSubmit}
      >
        <div className="border-2 border-gray-400 rounded-md my-5 p-5">
          <p className="text-1xl font-semibold text-center my-2">
            Add Physiotherapy Procedure
          </p>
          <div className="grid grid-cols-1  gap-2">
            <div className="col-span-8 bg-gray-50 p-5">
              <ToastContainer theme="colored" position="bottom-center" />
              <CustomInput
                className="w-full h-14 mt-5"
                size="large"
                id="search"
                name="search"
                label="Search physiotherapy procedure by name"
                placeholder="Search physiotherapy procedure by name"
                onChange={handleChange}
                value={searchText}
              />
              <div>
                <Flex className="mt-5" gap="middle" vertical>
                  <Table
                    rowSelection={{
                      type: "radio",
                      ...rowSelection,
                    }}
                    columns={columns}
                    dataSource={preparationsData}
                  />

                  {yesNoModal && selectedProcedure && (
                    <YesNoModal
                      showModal={yesNoModal}
                      setyesNoModal={setyesNoModal}
                      title={selectedProcedure.radiology_service_title}
                      content={"Add this item to order"}
                      yesAction={addItemToOrder}
                    />
                  )}
                  {mylocalOrder ? (
                    <div className="w-full">
                    <p className="text-1xl font-semibold text-center my-2">
                    Ordered Physiotherapy Examinations
                  </p>
                      <div>
                        {mylocalOrder &&
                          mylocalOrder.procedures &&
                        
                          mylocalOrder.procedures.map((x, index) => {
                            return (
                              <Card>
                                <div className="grid md:grid-cols-3 grid-cols-2">
                                  <div className="flex flex-col border-1 border-gray-200 p-2">
                                    <p>ITEM</p>
                                    <p className="font-bold">{x.procedure_title}</p>
                                  </div>
                                  <div className="flex flex-col border-1 border-gray-200 p-2">
                                    <p>CHARGE</p>
                                    <p className="font-bold">KES {x.charge.toString()}</p>
                                  </div>
                      

                                  <div className="flex flex-col border-1 border-gray-200 p-2 items-center justify-center">
                                    <p>REMOVE</p>
                                    <span className="text-lg text-default-400 cursor-pointer active:opacity-50  justify-center">
                                      <DeleteIcon
                                        onClick={() => handleDeletePhysiotherapyProcedureAction(x)}
                                      />
                                    </span>
                                  </div>
                                </div>
                              </Card>
                            );
                          })}
                      </div>
                    </div>
                  ) : (
                    <div></div>
                  )}
                </Flex>
              </div>
            </div>
          </div>
        </div>

        <div className="flex w-full items-center mt-2 justify-center col-span-1 md:col-span-2">
          <Button
            style={{
              background: currentColor,
              color: "white",
              width: 123,
              height: 50,
            }}
            onClick={()=>handleCloseRadiologyOrder()}
            className="w-40 rounded-md"
            color="primary"
            type="default"
          >
            Confirm and Close
          </Button>
        </div>
      </CustomForm>
    </div>
  );
}
