import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { useLocation } from 'react-router-dom'
import { useStateContext } from '../../../../contexts/ContextProvider'
import { getKeyValue, Spinner, Table, TableBody, TableCell, TableColumn, TableHeader, TableRow } from "@heroui/react"
import { CustomForm, CustomFormItem, CustomInput, CustomTextArea } from '../../../../components'
import * as Yup from "yup";
import { useFormik } from "formik";
import { toast, ToastContainer } from 'react-toastify'
import AdmissionNursingCadexDetails from './AdmissionNursingCadexDetails'

export default function AdmissionNursingCadexForm() {
    const [admissionNursingCadexEntries, setadmissionNursingCadexEntries] = useState([])

    const { currentColor } = useStateContext()
    const [selectedAdmission, setselectedAdmission] = useState()

    const [errors, setErrors] = useState([])
    const location = useLocation()
    const [admissionNursingCadex, setadmissionNursingCadex] = useState()
    const [selectedDependantId, setselectedDependantId] = useState()
    useEffect(() => {
        setselectedDependantId(location.state.dependant)
    }, [location])


    //Get admission

    const getAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
    const getDependantAdmission = async (id) => {
        await getAdmissionApi.request({
            "action": "GetDependantAdmission",
            "dependant": id
        })
    }


    useEffect(() => {
        if (getAdmissionApi.data) {

            if (getAdmissionApi.data.admission) {
                setselectedAdmission(getAdmissionApi.data.admission)
            }
        }

        console.log("getAdmissionApi.data", getAdmissionApi.data)
    }, [getAdmissionApi.data])

    useEffect(() => {
        if (selectedDependantId) {
            getDependantAdmission(selectedDependantId)
        }

    }, [selectedDependantId])

    const getAdmissionNursingCadexEntrysApi = useApi(hospitalsApi.hospitalInpatientAction)
    const getAdmissionNursingCadexEntry = async () => {
        getAdmissionNursingCadexEntrysApi.request({
            "action":"GetAdmissionNursingCadexEntry",
            "admission": selectedAdmission.id
        })
    }

    useEffect(() => {
        if (getAdmissionNursingCadexEntrysApi.data) {
            if (getAdmissionNursingCadexEntrysApi.data.admission_nursing_cadex){
                toast.success(getAdmissionNursingCadexEntrysApi.data.response_message)
                setadmissionNursingCadex(getAdmissionNursingCadexEntrysApi.data.admission_nursing_cadex)
            }
            if (getAdmissionNursingCadexEntrysApi.data.errors){
               setErrors(getAdmissionNursingCadexEntrysApi.data.errors)
            }
        }
        console.log("getAdmissionNursingCadexEntriesApi.data", getAdmissionNursingCadexEntrysApi.data)
    }, [getAdmissionNursingCadexEntrysApi.data])

    const addAdmissionNursingCadexEntriesApi = useApi(hospitalsApi.hospitalInpatientAction)

    const addAdmissionNursingCadexeEntry = async (data) => {
        addAdmissionNursingCadexEntriesApi.request(data)
    }

    // useEffect(() => {
    //     if (addAdmissionNursingCadexEntriesApi.data) {
    //         if (addAdmissionNursingCadexEntriesApi.data.admission_nursing_cadex){
    //             toast.success(addAdmissionNursingCadexEntriesApi.data.response_message)
    //             setadmissionNursingCadex(addAdmissionNursingCadexEntriesApi.data.admission_nursing_cadex)
    //         }
    //         if (addAdmissionNursingCadexEntriesApi.data.errors){
    //            setErrors(addAdmissionNursingCadexEntriesApi.data.errors)
    //         }
    //     }
    //     console.log("addAdmissionNursingCadexEntriesApi.data", addAdmissionNursingCadexEntriesApi.data)
    // }, [addAdmissionNursingCadexEntriesApi.data])



    useEffect(() => {
        if(selectedAdmission){
            getAdmissionNursingCadexEntry();
        }
        
    }, [selectedAdmission])

    const formik = useFormik({
        initialValues: {
            diagnosis: "",
            current_disease_history: "",
            past_medical_surgical_history: "",
            socio_economic_history: "",
            development_history: "",
            physical_examination: "",
        },

        validationSchema: Yup.object({
            diagnosis: Yup.string().required().label("Diagnosis"),
            current_disease_history: Yup.string().required().label("Current disease history"),
            past_medical_surgical_history: Yup.string().required().label("Past medico-surgical history"),
            socio_economic_history: Yup.string().required().label("Socio-economic history"),
            development_history: Yup.string().required().label("Development  history"),
            physical_examination: Yup.string().required().label("Physical examination  status"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log("VALZ", values);
            if (selectedAdmission) {

                const data = {
                    "action": "CreateAdmissionNursingCadex",
                    "admission": selectedAdmission.id,
                    "diagnosis": "Malaria",
                    "current_disease_history": "Crrently very ill",
                    "past_medical_surgical_history": "Past medical surgical history",
                    "socio_economic_history": "Socio economic history",
                    "past_obstetric_history": "Past obstetric history",
                    "development_history": "Developmet history ",
                    "physical_examination": "Physical examination"

                }
                addAdmissionNursingCadexeEntry(data)
            } else {
                // toast.error("No admission details available")
                console.log("No item")
            }


        },
    });


  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);




    return <div className='flex flex-col items-center justify-center'>
   <ToastContainer theme="colored" position="bottom-center" />
        {addAdmissionNursingCadexEntriesApi.loading ? <Spinner color='primary' /> : <div></div>}
       {admissionNursingCadex?<div className='w-full'>
        <p className='text-xl font-semibold text-center'>Admission Nursing Cadex</p>
        <AdmissionNursingCadexDetails admissionNursingCadex={admissionNursingCadex}/>
        </div>: <CustomForm
            layout="horizontal"
            handleFinish={formik.handleSubmit}
            className=" justify-center items-center w-full px-2 "
        >

            <div className='grid grid-cols-1 gap-2 md:grid-cols-2'>
                <CustomFormItem
                    touched={formik.touched.diagnosis}
                    error={formik.errors.diagnosis}
                >
                    <CustomTextArea
                        className="text-start"
                        id="diagnosis"
                        name="diagnosis"
                        onChange={formik.handleChange}
                        placeholder="Enter current diagnosis"
                        label="Enter current diagnosis"
                        size="large"
                        type="text"
                        value={formik.values.diagnosis}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.current_disease_history}
                    error={formik.errors.current_disease_history}
                >
                    <CustomTextArea
                        className="text-start"
                        id="current_disease_history"
                        name="current_disease_history"
                        onChange={formik.handleChange}
                        placeholder="Enter current current_disease_history"
                        label="Enter current current_disease_history"
                        size="large"
                        type="text"
                        value={formik.values.current_disease_history}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.past_medical_surgical_history}
                    error={formik.errors.past_medical_surgical_history}
                >
                    <CustomTextArea
                        className="text-start"
                        id="past_medical_surgical_history"
                        name="past_medical_surgical_history"
                        onChange={formik.handleChange}
                        placeholder="Enter past medical surgical history"
                        label="Enter past medical surgical history"
                        size="large"
                        type="text"
                        value={formik.values.past_medical_surgical_history}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.socio_economic_history}
                    error={formik.errors.socio_economic_history}
                >
                    <CustomTextArea
                        className="text-start"
                        id="socio_economic_history"
                        name="socio_economic_history"
                        onChange={formik.handleChange}
                        placeholder="Enter client socio economic history"
                        label="Enter client socio economic history"
                        size="large"
                        type="text"
                        value={formik.values.socio_economic_history}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.past_obstetric_history}
                    error={formik.errors.past_obstetric_history}
                >
                    <CustomTextArea
                        className="text-start"
                        id="past_obstetric_history"
                        name="past_obstetric_history"
                        onChange={formik.handleChange}
                        placeholder="Enter client past and present obstetric history (if applicable)"
                        label="Enter client past and present obstetric history (if applicable)"
                        size="large"
                        type="text"
                        value={formik.values.past_obstetric_history}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.development_history}
                    error={formik.errors.development_history}
                >
                    <CustomTextArea
                        className="text-start"
                        id="development_history"
                        name="development_history"
                        onChange={formik.handleChange}
                        placeholder="Enter client development history"
                        label="Enter client development history"
                        size="large"
                        type="text"
                        value={formik.values.development_history}
                    />
                </CustomFormItem>
                <CustomFormItem
                    touched={formik.touched.physical_examination}
                    error={formik.errors.physical_examination}
                >
                    <CustomTextArea
                        className="text-start"
                        id="physical_examination"
                        name="physical_examination"
                        onChange={formik.handleChange}
                        placeholder="Enter client physical examination history"
                        label="Enter client physical examination history"
                        size="large"
                        type="text"
                        value={formik.values.physical_examination}
                    />
                </CustomFormItem>

            </div>
            <button
                id="formikPrescription"
                style={{ background: currentColor }}
                className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
                color="primary"
                type="submit"
            >
                Submit
            </button>
        </CustomForm>}


    </div>
}
