import React from 'react'

export default function DependantDetailsBar({selectedDependant}) {
  return (
           
             <div className="grid grid-cols-2 md:grid-cols-4 bg-white border-2 border-gray-300 rounded-md shadow-md">
               <div className=" border-1 border-gray-300 p-2">
                 <p>Name</p>
                 <p>{selectedDependant.title}</p>
               </div>
               <div className=" border-1 border-gray-300 p-2">
                 <p>Gender</p>
                 <p>{selectedDependant.gender}</p>
               </div>
               <div className=" border-1 border-gray-300 p-2">
                 <p>Date of Birth</p>
                 <p>{selectedDependant.date_of_birth}</p>
               </div>
               <div className=" border-1 border-gray-300 p-2">
                 <p>Age</p>
                 <p>{selectedDependant.age} Years</p>
               </div>
             </div>
        
  )
}
