import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Timeline } from 'antd'

export default function PatientNursingCadexTimeline({selectedAdmission,updated,setupdated}) {

    const [patientNursingCadexEntries, setpatientNursingCadexEntries] = useState([])
    
    const getPatientNursingCadexEntriesApi=useApi(hospitalsApi.hospitalInpatientAction)

    const getPatientNursingCadexEntries=async()=>{
        await getPatientNursingCadexEntriesApi.request({
            "action":"GetPatientNursingCadexEntries",
            "admission": selectedAdmission.id
        })
    }

    useEffect(()=>{
        if(getPatientNursingCadexEntriesApi.data){
           if(getPatientNursingCadexEntriesApi.data.length){
            setpatientNursingCadexEntries(
                getPatientNursingCadexEntriesApi.data.map((i) => ({
                    label: i.created,
                    children: i.entry,
                }))
            );
           }
        }
        console.log("getPatientNursingCadexEntriesApi.data",getPatientNursingCadexEntriesApi.data)
    },[getPatientNursingCadexEntriesApi.data])


    useEffect(()=>{
        if(selectedAdmission){
            getPatientNursingCadexEntries()
        }
    },[selectedAdmission])


    useEffect(()=>{
        if(updated && selectedAdmission){
            getPatientNursingCadexEntries() 
        }
    },[updated])

  return (
    <div className='w-full mt-5 flex justify-start items-start'>
    <p></p>
    <Timeline className='w-full' mode='left' items={patientNursingCadexEntries}/>
    
    </div>
  )
}
