import React, { useEffect, useState } from "react";
import * as Yup from "yup";

import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";

import { Modal } from "antd";
import { useStateContext } from "../../../../contexts/ContextProvider";
import buttonGreen from '../../../../assets/images/button_green.png'
import buttonRed from '../../../../assets/images/button_red.png'
import { Button } from "@heroui/react";
import { CustomForm, CustomFormItem, CustomInput, CustomTextArea } from "../../../../components";
import useApi from "../../../../hooks/useApi";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";


export default function TreatmentSheetModal({
  ismodalOpen,
  setismodalOpen,
  selectedRowKeys,
  selectedAdmissionPrescriptionItem,
  setselectedAdmissionPrescriptionItem,
  modalTitle = "Select department to refer",
  updated,
  setUpdated,
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();

  const { currentColor } = useStateContext()

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);


  useEffect(() => {
    console.log("at modal", selectedAdmissionPrescriptionItem)
  }, [selectedAdmissionPrescriptionItem])




  const formik = useFormik({
    initialValues: {
      department: "",
    },

    validationSchema: Yup.object({
      department: Yup.object().required("Department is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      const data = {
        action: "CreateDepartmentalVisit",

        department: values.department.value,
        dependant: selectedRowKeys[0],
      };

      console.log("data...", data);



      resetForm();
    },
  });

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setismodalOpen(false);
  };
  const handleCancel = () => {
    setismodalOpen(false);
  };



  const [comment, setComment] = useState()

  const updateItemApi = useApi(hospitalsApi.hospitalStaffAction)
  const handleUpdateItem=async(item)=>{
    console.log("item to upfdate",item)
    if(comment){
      toast.warn(comment)
      console.log("comment",comment)
      await updateItemApi.request({
        "action":"UpdateHospitalPrescriptionItemAdministration",
        "hospital_prescription_item_administration":item.id,
        "comment":comment,
        "is_administered":"true"
    })
    }
    setComment(null)
  }

  useEffect(()=>{
    if(updateItemApi.data){
      if(updateItemApi.data.hospital_prescription_item){
        toast.success(updateItemApi.data.response_message)
        setselectedAdmissionPrescriptionItem(updateItemApi.data.hospital_prescription_item)
      }
    }
  },[updateItemApi.data])

  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={selectedAdmissionPrescriptionItem.title}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />


        <p className="text-xl text-center font-semibold">Doses: {selectedAdmissionPrescriptionItem.administrations.length}</p>
        <div>

          {
            selectedAdmissionPrescriptionItem.administrations.map(element => {
              const colors = [
                "bg-red-500",
                "bg-blue-500",
                "bg-yellow-500",
                "bg-purple-500",
                "bg-orange-500",
              ];

              const color = currentColor || `bg-${element.color}-500`;

              return <div key={element.id} className="flex m-4 relative">
                <div
                  className={`${color} w-0.5 h-6 translate-x-20 translate-y-56 opacity-60 sm:hidden`}
                ></div>
                <div
                  className={`${color} w-0.5 h-6 translate-x-80 translate-y-56 opacity-60 sm:hidden`}
                ></div>
                <div className="hidden items-start w-44 pt-0.5 relative sm:flex">
                  <div className="w-4/5 text-gray-800">{element.administration_date}</div>
                  <div
                    className={`${color} w-px h-full translate-x-5 translate-y-10 opacity-30`}
                  ></div>
                  <img
                    style={{ width: 50, height: 50 }}
                    src={element.is_administered === "false" ? buttonRed : buttonGreen}
                    alt="icon"
                    className={`${color} w-10 p-1 rounded-lg z-20`}
                  />
                  <div
                    className={`${color} h-px w-8 translate-y-5 opacity-30`}
                  ></div>
                </div>
                <div className="border border-gray-600 rounded-lg px-8 py-4 bg-gray-100 w-full text-center z-10 sm:w-96">
                  <div className="text-xl font-medium">{element.administration_time}</div>
                  <div className="text-gray-800 mb-6 sm:mb-8 sm:text-xs">
                    {element.location}
                    <span className="sm:hidden">{element.administration_date}</span>
                  </div>
                  <div className="mb-4 text-center">{element.administration_time}</div>
                  <div className="flex flex-wrap mb-6 justify-center">
                    <p>{element.comment}</p>
                  </div>
                  <img
                    src={element.is_administered === "false" ? buttonRed : buttonGreen}
                    alt="icon"
                    className={`${color} w-8 p-1 rounded-lg z-20 absolute left-4 top-4 sm:hidden`}
                  />

                  {element.is_administered === "false" ? <div>
                    <CustomTextArea
                    className="text-start"
                    id={element.id}
                    name="comment"
                    onChange={(e)=>setComment(e.target.value)}
                    placeholder="Enter comment"
                    label="Enter comment"
                    size="large"
                    type="text"
                   
                  />
                    <Button onPress={()=>handleUpdateItem(element)}
                      className={`${color} text-gray-950 font-medium px-4 py-1 rounded-md mx-auto cursor-pointer hover:text-white`}
                    >
                      Update
                    </Button>
                  </div> : <div></div>}
                </div>
              </div>

            })
          }
        </div>
      </Modal>
    </div>
  );
}
