import React, { useEffect, useState } from 'react'
import { CustomForm, CustomFormItem, CustomInput, CustomSelectReactSelect, CustomTextArea, Loading } from '../../../components'
import * as Yup from "yup";
import { useFormik } from "formik";
import { useStateContext } from '../../../contexts/ContextProvider';
import useApi from '../../../hooks/useApi';
import hospitalsApi from '../../../api/hospitals/hospitalsApi';
import { toast, ToastContainer } from 'react-toastify';
import { useLocation } from 'react-router-dom';
import { getKeyValue, Table, TableBody, TableCell, TableColumn, TableHeader, TableRow } from "@heroui/react";
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, XAxis, YAxis } from 'recharts';
import { Tooltip } from 'antd';

export default function BloodPressureForm() {
    const { currentColor } = useStateContext()
    const [selectedAdmission, setselectedAdmission] = useState()
    const [errors, setErrors] = useState([])

    const location = useLocation()
    const [selectedDependantId, setselectedDependantId] = useState()
    useEffect(() => {
        setselectedDependantId(location.state.dependant)
    }, [location])


    //Get admission

    const getAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
    const getDependantAdmission = async (id) => {
        await getAdmissionApi.request({
            "action": "GetDependantAdmission",
            "dependant": id
        })
    }

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);
    useEffect(() => {
        if (getAdmissionApi.data) {

            if (getAdmissionApi.data.admission) {
                setselectedAdmission(getAdmissionApi.data.admission)
            }
        }

        console.log("getAdmissionApi.data", getAdmissionApi.data)
    }, [getAdmissionApi.data])

    useEffect(() => {
        if (selectedDependantId) {
            getDependantAdmission(selectedDependantId)
        }

    }, [selectedDependantId])


    //Create blood pressure entry

    const inpatientApi = useApi(hospitalsApi.hospitalInpatientAction)

    const createBloodPressureEntry = async (data) => {
        await inpatientApi.request(data)
    }


    useEffect(() => {
        if (inpatientApi.data) {

            if (inpatientApi.data.blood_pressure_chart_entry) {

                retrieveAdmissionBloodPressureEntries()
                prescriptionFormik.resetForm()
            }
        }

        console.log("inpatientApi.data", inpatientApi.data)
    }, [inpatientApi.data])





    //Retrieve blood pressure entries for selected admission
    const [bloodPressureChartData, setbloodPressureChartData] = useState([])
    const [bloodPressureEntries, setbloodPressureEntries] = useState([])
    const admissionBloodPressureEntriesApi = useApi(hospitalsApi.hospitalInpatientAction)

    const retrieveAdmissionBloodPressureEntries = async () => {
        admissionBloodPressureEntriesApi.request({
            "action": "GetAdmissionBloodPressureEntries",
            "admission": selectedAdmission.id

        })
    }


    useEffect(() => {
        if (admissionBloodPressureEntriesApi.data) {
            if (admissionBloodPressureEntriesApi.data.length) {
                setbloodPressureEntries(admissionBloodPressureEntriesApi.data)
                setbloodPressureChartData(
                    admissionBloodPressureEntriesApi.data.map((i) => ({
                        date: i.created,
                        systolic_pressure: i.systolic_pressure,
                        diastolic_pressure: i.diastolic_pressure,
                    }))
                );
            }
        }
        console.log("admissionBloodPressureEntriesApi.data", admissionBloodPressureEntriesApi.data)
    }, [admissionBloodPressureEntriesApi.data])


    useEffect(() => {
        if (selectedAdmission) {
            retrieveAdmissionBloodPressureEntries()
        }
    }, [selectedAdmission])

    const prescriptionFormik = useFormik({
        initialValues: {
            diastolic_pressure: "",
            systolic_pressure: "",
        },

        validationSchema: Yup.object({
            diastolic_pressure: Yup.number().required().label("Diastolic pressure"),
            systolic_pressure: Yup.number().required().label("Systolic pressure"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log("VALZ", values);
            if (selectedAdmission) {

                const data = {
                    "action": "CreateBloodPressureChartEntry",
                    "admission": selectedAdmission.id,
                    "diastolic_pressure": values.diastolic_pressure,
                    "systolic_pressure": values.systolic_pressure
                }
                createBloodPressureEntry(data)
            } else {
                toast.error("No admission details available")
                console.log("No item")
            }


        },
    });


    const columns = [
        {
            key: "created",
            label: "Date",
        },
        {
            key: "systolic_pressure",
            label: "Systolic Pressure",
        },
        {
            key: "diastolic_pressure",
            label: "Diastolic Pressure",
        },
    ];


    return inpatientApi.loading ? <Loading /> : <div className=" rounded-sm border-gray-200 mt-5 border-2 bg-white">
        <ToastContainer theme="colored" position="bottom-center" />
        <p className="text-center text-xl font-semibold">
            Add New Blood Pressure Entry
        </p>
        <CustomForm
            layout="horizontal"
            handleFinish={prescriptionFormik.handleSubmit}
            className="grid grid-cols-1 md:grid-cols-3 gap-4  justify-center items-center w-full px-2 "
        >


            <CustomFormItem
                touched={prescriptionFormik.touched.diastolic_pressure}
                error={prescriptionFormik.errors.diastolic_pressure}
            >
                <CustomInput
                    className="text-start"
                    id="diastolic_pressure"
                    name="diastolic_pressure"
                    onChange={prescriptionFormik.handleChange}
                    placeholder="Enter diastolic pressure"
                    label="Enter diastolic pressure"
                    size="large"
                    type="text"
                    value={prescriptionFormik.values.diastolic_pressure}
                />
            </CustomFormItem>
            <CustomFormItem
                touched={prescriptionFormik.touched.systolic_pressure}
                error={prescriptionFormik.errors.systolic_pressure}
            >
                <CustomInput
                    className="text-start"
                    id="systolic_pressure"
                    name="systolic_pressure"
                    onChange={prescriptionFormik.handleChange}
                    placeholder="Enter systolic pressure"
                    label="Enter systolic pressure"
                    size="large"
                    type="text"
                    value={prescriptionFormik.values.systolic_pressure}
                />
            </CustomFormItem>

            <button
                id="formikPrescription"
                style={{ background: currentColor }}
                className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
                color="primary"
                type="submit"
            >
                Submit
            </button>
        </CustomForm>
        <div>
            <p className='text-xl font-semibold text-center'>Recent Blood Pressure Entries</p>
            <Table aria-label="Example empty table">
                <TableHeader columns={columns}>
                    {(column) => <TableColumn key={column.key}>{column.label}</TableColumn>}
                </TableHeader>
                {bloodPressureEntries && bloodPressureEntries.length ? <TableBody items={bloodPressureEntries}>
                    {(item) => (
                        <TableRow key={item.created}>
                            {(columnKey) => <TableCell>{getKeyValue(item, columnKey)}</TableCell>}
                        </TableRow>
                    )}
                </TableBody> : <TableBody emptyContent={"No rows to display."}>{[]}</TableBody>}

            </Table>

        </div>

        <div className='w-full'>
            <h1 className="text-heading text-xl font-semibold text-center">Blood Pressure Chart</h1>
            <ResponsiveContainer className="w-full" width="100%" aspect={3}>
                <LineChart data={bloodPressureChartData} margin={{ right: 10 }}>
                    <CartesianGrid />
                    <XAxis dataKey="date" interval={"preserveStartEnd"} />
                    <YAxis></YAxis>
                    <Legend />
                    <Tooltip />
                    <Line
                        dataKey="diastolic_pressure"
                        stroke="black"
                        activeDot={{ r: 8 }}
                    />
                    <Line dataKey="systolic_pressure" stroke="red" activeDot={{ r: 8 }} />
                </LineChart>
            </ResponsiveContainer>
        </div>
    </div>



}
