import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'

export default function AdmissionPrescriptionOrders({selectedAdmission}) {

  const [prescriptioOrders, setprescriptioOrders] = useState([])
    const [data, setData] = useState([])
  
  const getAdmissionPrescriptionOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
  const getAdmissionPrescriptionOrders=async()=>{
    await getAdmissionPrescriptionOrdersApi.request({
      "action": "GetAdmissionPrescriptionOrders",
      "admission":selectedAdmission.id
   
  })
  }
  useEffect(()=>{
    if(getAdmissionPrescriptionOrdersApi.data){
     if(getAdmissionPrescriptionOrdersApi.data.length){
        setprescriptioOrders(getAdmissionPrescriptionOrdersApi.data)
     }
    }
    console.log("getAdmissionPrescriptionOrdersApi.data",getAdmissionPrescriptionOrdersApi.data)
  },[getAdmissionPrescriptionOrdersApi.data])
  useEffect(()=>{
    if(selectedAdmission){
      getAdmissionPrescriptionOrders()
    }
  },[selectedAdmission])

          useEffect(() => {
            if (prescriptioOrders) {
              if (prescriptioOrders.length) {
                setData(prescriptioOrders.map((i, index) => ({
                  label: `${i.created}  ${i.destination_department_title}`,
                  key: index+1,
                  children: <div>
                    {
                      i.items && i.items.length ? <div>
        
                        {
                          i.items.map((y,yIn) => {
                            return <div>
                              <p className=''>
                              <span className='mx-2'>{yIn+1}.</span>
                              <span className='mx-2'>{y.entity_sub_store_receipt_title}</span>
                              <span className='mx-2 font-semibold'>KES {parseFloat(y.item_total_price).toFixed(2).toString()}</span>
                              </p>
        
                            </div>
                          })
                        }
                      </div> : <div></div>
                    }
                  </div>
                })))
              }
            }
        
            console.log("prescriptionOrders", prescriptioOrders)
          }, [prescriptioOrders])

  return (
    <div>
    <p className='text-2xl font-semibold text-center'>Admission Prescription Orders</p>
    
    </div>
  )
}
