
import React, { useEffect, useState } from "react";
import { useStateContext } from "../../../contexts/ContextProvider";
import { useLocation } from "react-router-dom";
import { useMediaQuery } from "react-responsive";
import useApi from "../../../hooks/useApi";
import dependantsApi from "../../../api/dependantsApi";
import AdmissionDetails from "./Admissions/AdmissionDetails";
import { TabPaneWrapper } from "../../../components/TabPaneWrapper";
import { Tab, Tabs, TabList, CardBody, Card, } from "@heroui/react";
import 'react-tabs/style/react-tabs.css';
import BloodPressureForm from "./BloodPressureForm";
import AdmissionNursingCadex from "./AdmissionNursingCadex";
import ComprehensionFirstCadex from "./ComprehensionFirstCadex/ComprehensionFirstCadex";
import ContinuationSheet from "./PatientNursingCadex/PatientNursingCadex";
import NursingCarePlan from "./NursingCarePlan/NursingCarePlan";
import DischargeSummary from "./DischargeSummary/DischargeSummary";
import DependantDetailsBar from "../../../components/hospitals/DependantDetailsBar";
import TreatmentSheet from "./TreatmentSheet/TreatmentSheet";
import DepartmentalOrders from "./DepartmentalOrders/DepartmentalOrders";
import RadiologyOrders from "./RadiologyOrders/RadiologyOrders";
import AdmissionChargeSheet from "./ChargeSheet/AdmissionChargeSheet";


export default function AdmissionDashboard() {
  
  const isBigScreen = useMediaQuery({ query: "(min-width: 1824px)" });
  const isTabletOrMobile = useMediaQuery({ query: "(max-width: 1224px)" });
  const isPortrait = useMediaQuery({ query: "(orientation: portrait)" });
  const isRetina = useMediaQuery({ query: "(min-resolution: 2dppx)" });
  const location = useLocation();
  const { loggedInUser } = useStateContext()
  const [selectedDependantId, setselectedDependantId] = useState();
  const [selectedDepartmentId, setselectedDepartmentId] = useState();
  const [selectedDepartmentalVisitId, setselectedDepartmentalVisitId] =
    useState();
  const [selectedDependant, setselectedDependant] = useState();


  const [placement, setplacement] = useState("top")
  useEffect(() => {
    if (location && location.state && location.state.dependant) {
      setselectedDependantId(location.state.dependant);
      setselectedDepartmentId(location.state.department);
      setselectedDepartmentalVisitId(location.state.visit);
    }
  }, [location]);

  const dependantDetailsApi = useApi(dependantsApi.dependantsAction);

  const getDependantDetails = async () => {
    await dependantDetailsApi.request({
      action: "GetDependantDetails",
      dependant_id: selectedDependantId,
    });
  };



  useEffect(() => {
    console.log("dependantDetailsApi.data", dependantDetailsApi.data);
    if (dependantDetailsApi.data && dependantDetailsApi.data.dependant) {
      setselectedDependant(dependantDetailsApi.data.dependant);
    }
  }, [dependantDetailsApi.data]);



  useEffect(() => {
    if (selectedDependantId !== null) {
      getDependantDetails(selectedDependantId);

    }
  }, [selectedDependantId]);



  console.log("location", location);
  const { currentColor } = useStateContext();
  const onChange = (key) => {
    console.log(key);
  };
  const items = [
    {
      key: "1",
      label: "Admission Details",
      children: <AdmissionDetails />
    },
    {
      key: "2",
      label: "Admission Nursing Cadex",
      children: <AdmissionNursingCadex/>,
    },
    {
      key: "3",
      label: "Blood Pressure Chart",
      children: <BloodPressureForm />,
    },
    {
      key: "5",
      label: "Comprehension First Cadex",
      children: <ComprehensionFirstCadex/>,
    },
    {
      key: "6",
      label: "Continuation Sheet",
      children: <ContinuationSheet/>,
    },
    {
      key: "7",
      label: "Discharge Summary",
      children: <DischargeSummary/>,
    },
    {
      key: "8",
      label: "Maternity Admission",
      children: "Maternity Admission",
    },
    {
      key: "9",
      label: "Nursing Care Plan",
      children: <NursingCarePlan/>,
    },
    {
      key: "10",
      label: "Patient Nursing Cadex",
      children:<ContinuationSheet/>,
    },
    {
      key: "11",
      label: "Theatre Operation Notes",
      children: "Theatre Operation Notes",
    },
    {
      key: "12",
      label: "Treatment Sheet",
      children: <TreatmentSheet/>,
    },
    {
      key: "13",
      label: "Departmental Orders",
      children: <DepartmentalOrders/>,
    },
    {
      key: "14",
      label: "Admission Charge Sheet",
      children: <AdmissionChargeSheet/>,
    },

  ];

  useEffect(()=>{
    if(isBigScreen){
      setplacement("start")
    }
  },[])


  return (
    <div className="mt-16 md:mt-2 grid grid-cols-1 md:grid-cols-12 py-5">
      <div className="col-span-1 hidden md:block"></div>
      <div className="col-span-10  ">
        <p className="text-2xl font-semibold text-center ">
          {loggedInUser ? loggedInUser.employment_department_title : "No department details"}
        </p>

        {selectedDependant ? (
          <DependantDetailsBar selectedDependant={selectedDependant}/>
        ) : (
          <div></div>
        )}
        <div className="w-full mt-5">
          <Tabs  className="w-full grid grid-flow-row md:w-80" aria-label="Options" placement={placement}  radius="none" size="lg">

            {
              items.map((x, index) => {
                return <Tab key={x.key} title={x.label}  className="w-full" >
                  <Card className="w-full" radius="none">
                    <CardBody className="w-full">
                     {x.children}
                    </CardBody>
                  </Card>
                </Tab>
              })
            }


          </Tabs>
        </div>
      </div>
      <div className="col-span-1 hidden md:block"></div>
    </div>
  );
}
