import { Accordion, AccordionItem } from '@heroui/react'
import React from 'react'

export default function ComprehensionFirstCadexDetails({ comprehensionFirstcadex }) {
  return (
    <div className='w-full'>


      <Accordion variant='splitted' className='w-full' isCompact>
        <AccordionItem key="1" aria-label="Diagnosis" title={
          <p className='font-bold'>Neck</p>
        }>
          {comprehensionFirstcadex.neck}
        </AccordionItem>
        <AccordionItem key="2" aria-label="Chest" title={
          <p className='font-bold'>Chest</p>
        }>
          {comprehensionFirstcadex.chest}
        </AccordionItem>
        <AccordionItem key="3" aria-label="Upper Extremeties" title={
          <p className='font-bold'>Upper Extremeties</p>
        } >
          {comprehensionFirstcadex.upper_extremities}
        </AccordionItem>
        <AccordionItem key="4" aria-label="Abdomen" title={
          <p className='font-bold'>Abdomen</p>
        } >
          {comprehensionFirstcadex.abdomen}
        </AccordionItem>
        <AccordionItem key="5" aria-label="Inspection" title={
          <p className='font-bold'>Inspection</p>
        } >
          {comprehensionFirstcadex.inspection}
        </AccordionItem>
        <AccordionItem key="6" aria-label="Palpation" title={
          <p className='font-bold'>Palpation</p>
        } >
          {comprehensionFirstcadex.palpation}
        </AccordionItem>
        <AccordionItem key="7" aria-label="Ausculation" title={
          <p className='font-bold'>Ausculation</p>
        }>
          {comprehensionFirstcadex.ausculation}
        </AccordionItem>
        <AccordionItem key="8" aria-label="Lower extremeties" title={
          <p className='font-bold'>Lower extremeties</p>
        }>
          {comprehensionFirstcadex.lower_extremities}
        </AccordionItem>
        <AccordionItem key="9" aria-label="Vitals" title={
          <p className='font-bold'>Vitals</p>
        }>
          <div className='grid grid-cols-1 md:grid-cols-2'>
            <div className='grid grid-cols-2'>
              <p>Temparature</p>
              <p>{comprehensionFirstcadex.temparature}</p>
            </div>
            <div className='grid grid-cols-2'>
              <p>Pulse</p>
              <p>{comprehensionFirstcadex.pulse}</p>
            </div>
            <div className='grid grid-cols-2'>
              <p>Respiration</p>
              <p>{comprehensionFirstcadex.respiration}</p>
            </div>
            <div className='grid grid-cols-2'>
              <p>Diastolic Pressure</p>
              <p>{comprehensionFirstcadex.diastolic_pressure}</p>
            </div>
            <div className='grid grid-cols-2'>
              <p>Systolic Pressure</p>
              <p>{comprehensionFirstcadex.systolic_pressure}</p>
            </div>
          </div>
        </AccordionItem>
      </Accordion>
    </div>
  )
}
